package com.digitalbeavertz.ruqya

import com.digitalbeavertz.ruqya.core.playlist
import com.digitalbeavertz.ruqya.data.Content
import com.digitalbeavertz.ruqya.data.Evidence
import com.digitalbeavertz.ruqya.data.Step
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** Reads the real assets/ruqya.json (generated by tools/build_content.py). */
class ContentTest {
    private val content = Content.parse(File("src/main/assets/ruqya.json").readText())

    @Test fun sessionsAndRoutinesResolve() {
        assertEquals(listOf("eye", "husda", "full", "sihr", "jinn", "sick", "distress", "family"), content.sessions.map { it.id })
        assertEquals(listOf("morning", "evening", "bedtime"), content.routines.map { it.id })
        (content.sessions + content.routines).forEach { s -> assertTrue(s.id, s.steps.isNotEmpty()) }
    }

    @Test fun evilEyeFollowsTheGuide() {
        // The ten steps of 'Ruqyah sahihi kwa kujitibu na kijicho', in order.
        val eye = content.session("eye")!!
        val ids = eye.steps.map {
            when (it) {
                is Step.Recite -> it.passage.id
                is Step.Say -> it.dua.id
                is Step.Do -> it.action.id
            }
        }
        assertEquals(listOf("prepare", "fatiha", "kursi", "baqarah_end", "ikhlas", "falaq", "nas", "jibril", "adhhib", "wipe"), ids)
        assertEquals(3, eye.steps.last().count)
    }

    @Test fun countsComeFromTheHadith() {
        assertEquals(3, content.dua("pain_bismillah")!!.count)
        assertEquals(7, content.dua("pain_audhu")!!.count)
        assertEquals(7, content.dua("visit")!!.count)
        assertEquals(3, content.dua("bismillah_ladhi")!!.count)
    }

    @Test fun everyRecitedFileIsInTheAudioPack() {
        val pack = content.audioFiles.toSet()
        (content.sessions + content.routines).forEach { s ->
            s.steps.forEach { st ->
                val passages = when (st) {
                    is Step.Recite -> listOf(st.passage)
                    is Step.Do -> st.action.passages
                    is Step.Say -> emptyList()
                }
                playlist(passages, st.count, true).forEach { assertTrue("${s.id}: $it", it in pack) }
            }
        }
    }

    @Test fun ninetyNineNamesEachWithASource() {
        val names = content.names.list
        assertEquals(99, names.size)
        assertEquals(81, names.count { it.ayah != null })
        // 18 from the Sunnah: 17 with a hadith in the five collections, al-Muhsin cited from at-Tabarani.
        assertEquals(17, names.count { it.hadith != null })
        assertEquals(1, names.count { it.cite != null })
        assertEquals("اللَّهُ", names.first().ar)
        assertEquals("59:22", names.first().ayah!!.key)
        assertEquals("الوِتْرُ", names.last().ar)
    }

    @Test fun madinahTextEndsWithTheVerseNumber() {
        val kursi = content.passages.getValue("kursi").ayahs.single()
        assertTrue(kursi.hafs.endsWith("\u00a0٢٥٥"))
        // Tanzil writes shadda before fatha.
        assertTrue(kursi.tanzil.startsWith("ٱللَّهُ"))
    }

    @Test fun routinesStartWithTheRecommendedAdhkar() {
        val morning = content.session("morning")!!
        val optional = morning.steps.filter { it.optional }.map { it.key }
        assertEquals(listOf("d:subhanallah_100", "d:tahlil_100", "d:istighfar_100"), optional)
        // Nothing chosen yet: everything except the 100-times adhkar.
        assertEquals(morning.steps.size - 3, morning.chosen(null).size)
        // The person's choice wins, in the routine's order.
        assertEquals(listOf("d:sayyid_istighfar", "d:tahlil_100"), morning.chosen(setOf("d:tahlil_100", "d:sayyid_istighfar")).map { it.key })
        // Sessions are never filtered.
        assertEquals(content.session("eye")!!.steps, content.session("eye")!!.chosen(null))
    }

    @Test fun stepKeysAreUniqueWithinEachRoutine() {
        content.routines.forEach { r -> assertEquals(r.id, r.steps.size, r.steps.map { it.key }.toSet().size) }
    }

    @Test fun morningAndEveningWordingDiffer() {
        assertTrue(content.dua("asbahna_mulk")!!.ar.startsWith("أَصْبَحْنَا"))
        assertTrue(content.dua("amsayna_mulk")!!.ar.startsWith("أَمْسَيْنَا"))
        val evening = content.session("evening")!!.steps.map { it.key }
        assertTrue("d:amsayna_mulk" in evening && "d:asbahna_mulk" !in evening)
        assertEquals(3, content.session("evening")!!.steps.first { it.key == "d:kalimat" }.count)
    }

    @Test fun everyAdhkarShowsItsFadhila() {
        listOf("morning", "evening", "bedtime").forEach { id ->
            content.session(id)!!.steps.forEach { st ->
                assertTrue("$id ${st.key} has no fadhila", st.virtues.isNotEmpty() || st.fadlNote != null)
            }
        }
        // The Quls carry both: 'they suffice you' (Abu Dawud 5082) and their own merit.
        val ikhlas = content.session("morning")!!.steps.first { it.key == "p:ikhlas" }
        assertEquals(listOf("5082", "5013"), ikhlas.virtues.map { it.source.n })
    }

    @Test fun husdaSessionAndArticle() {
        val husda = content.session("husda")!!
        val keys = husda.steps.map { it.key }
        // Al-Falaq ends with refuge from the envier; Jibril's ruqya names the envier's eye.
        assertTrue("p:falaq" in keys && "d:jibril" in keys && "d:children" in keys)
        assertEquals("husda", husda.howTo!!.article)
        val article = content.article("husda")!!
        assertTrue(article.evidence.any { it is Evidence.Quran && it.passage.ayahs.single().key == "113:5" })
        assertEquals(article.bodyEn.size, article.bodySw.size)
    }

    @Test fun everySessionExplainsHowToDoIt() {
        content.sessions.forEach { s ->
            val h = s.howTo
            assertTrue("${s.id} has no how-to", h != null && h.stepsEn.isNotEmpty())
            assertEquals(s.id, h!!.stepsEn.size, h.stepsSw.size)
            h.article?.let { assertTrue("${s.id}: unknown article $it", content.article(it) != null) }
        }
    }

    @Test fun gradesShownForSunanCollections() {
        val visit = content.dua("visit")!!.sources.first()
        assertEquals("abudawud", visit.book)
        assertTrue(visit.grade!!.en.contains("al-Albani"))
        assertEquals("Sahih", content.dua("jibril")!!.sources.first().grade!!.en)
    }
}
